/*
 * A257982  Sequence (d(n)) generated by Rule 3 (in Comments) with a(1) = 1
 *          and d(1) = 1.
 * https://oeis.org/A257982
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, easy
 * Formula:   not stated
 * Range:     i8 n <= 135, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generate the sequence of d(n) from Rule 3 in the comments.
   a(1) = 1, d(1) = 1, and subsequent terms are produced by
   the algorithm described in the OEIS entry.  The function
   returns the n-th d(n) (this is the a(n) listed in the OEIS
   b-file).  Memoization allows arbitrary call order. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* seq_t and idx_t are supplied by the build environment. */
typedef seq_t seq_t;
typedef idx_t idx_t;

/* Cached sequence values.  A[k] = a(k+1), D[k] = d(k+1). */
static seq_t *A = NULL;
static seq_t *D = NULL;
static idx_t  size  = 0;
static idx_t  cap   = 0;

/* Linear search: true if v occurs in arr[0..len-1]. */
static bool in_array(const seq_t *arr, idx_t len, seq_t v)
{
    for (idx_t i = 0; i < len; ++i)
        if (arr[i] == v) return true;
    return false;
}

/* Ensure the arrays can hold at least need elements. */
static void ensure_capacity(idx_t need)
{
    if (need <= cap) return;
    cap = cap == 0 ? 16 : cap * 2;
    while (cap < need) cap <<= 1;
    A = (seq_t *)realloc(A, sizeof(seq_t) * cap);
    D = (seq_t *)realloc(D, sizeof(seq_t) * cap);
}

/* Append a new term (a_next, d_next) to the cached sequence. */
static void append_term(seq_t a_next, seq_t d_next)
{
    ensure_capacity(size + 1);
    A[size] = a_next;
    D[size] = d_next;
    ++size;
}

/* Main entry point.  n is 1‑based. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* Not used; avoid UB. */

    /* Initialise if this is the first call. */
    if (size == 0) {
        ensure_capacity(16);
        A[0] = (seq_t)1;          /* a(1) */
        D[0] = (seq_t)1;          /* d(1) */
        size = 1;
    }

    /* Generate terms up to n.  Each iteration produces a(k+1). */
    while (size < n) {
        seq_t a_k = A[size - 1];   /* current a(k) */
        seq_t d_next;
        seq_t a_next;
        bool found = false;

        /* ---- Step 1: negative h ---- */
        seq_t lower = 1 - a_k;      /* exclusive lower bound: 1 - a(k) */

        /* Search h from the least (most negative) upwards to -1. */
        for (seq_t h = lower + 1; h < 0; ++h) {
            if (!in_array(D, size, h) && !in_array(A, size, a_k + h)) {
                d_next = h;
                found = true;
                break;                /* least such h found */
            }
        }

        /* ---- Step 2: positive h ---- */
        if (!found) {
            seq_t h = 1;
            while (true) {
                if (!in_array(D, size, h) && !in_array(A, size, a_k - h)) {
                    d_next = h;
                    break;
                }
                ++h;
            }
        }

        a_next = a_k + d_next;
        append_term(a_next, d_next);
    }

    /* Return the requested d(n). */
    return D[n - 1];
}
